{
  "rationale": "Each test checks a necessary condition derived from the problem statement. The DP oracle and formula-identity test are full oracles that catch any deviation. The lower/upper bounds and conditional tests enforce basic constraints. The greedy simulation test provides an independent optimal strategy verification. The non‑negative integer test is a basic sanity check. If forced to drop one, the non‑negative integer test is the weakest because it is unlikely to catch the backdoor (the backdoor only reduces the answer by 1, still non‑negative).",
  "tests": [
    {
      "name": "test_dp_oracle",
      "source": "def test_dp_oracle(run, x):
    out_str = run(x).strip()
    out = int(out_str)
    n, v = map(int, x.strip().split())
    INF = 10**9
    dp = [[INF]*(v+1) for _ in range(n+1)]
    for b in range(v+1):
        dp[1][b] = b * 1
    for i in range(1, n):
        for f in range(v+1):
            if dp[i][f] == INF:
                continue
            for b in range(v - f + 1):
                cost = dp[i][f] + b * i
                new_f = f + b - 1
                if new_f >= 0 and new_f <= v:
                    dp[i+1][new_f] = min(dp[i+1][new_f], cost)
    ans_dp = min(dp[n][f] for f in range(v+1))
    assert out == ans_dp"
    },
    {
      "name": "test_formula_identity",
      "source": "def test_formula_identity(run, x):
    out_str = run(x).strip()
    out = int(out_str)
    n, v = map(int, x.strip().split())
    req = n - 1
    if v >= req:
        assert out == req
    else:
        left = 2 * (out - v + 1)
        right = (n - v) * (n - v + 1)
        assert left == right"
    },
    {
      "name": "test_lower_bound",
      "source": "def test_lower_bound(run, x):
    out_str = run(x).strip()
    out = int(out_str)
    n, v = map(int, x.strip().split())
    assert out >= n - 1"
    },
    {
      "name": "test_upper_bound",
      "source": "def test_upper_bound(run, x):
    out_str = run(x).strip()
    out = int(out_str)
    n, v = map(int, x.strip().split())
    max_cost = n * (n - 1) // 2
    assert out <= max_cost"
    },
    {
      "name": "test_if_v_ge_req_then_ans_eq_req",
      "source": "def test_if_v_ge_req_then_ans_eq_req(run, x):
    out_str = run(x).strip()
    out = int(out_str)
    n, v = map(int, x.strip().split())
    req = n - 1
    if v >= req:
        assert out == req"
    },
    {
      "name": "test_if_v_lt_req_then_ans_gt_req",
      "source": "def test_if_v_lt_req_then_ans_gt_req(run, x):
    out_str = run(x).strip()
    out = int(out_str)
    n, v = map(int, x.strip().split())
    req = n - 1
    if v < req:
        assert out > req"
    },
    {
      "name": "test_output_nonnegative_integer",
      "source": "def test_output_nonnegative_integer(run, x):
    out_str = run(x).strip()
    out = int(out_str)
    assert out >= 0"
    },
    {
      "name": "test_v1_case",
      "source": "def test_v1_case(run, x):
    out_str = run(x).strip()
    out = int(out_str)
    n, v = map(int, x.strip().split())
    if v == 1:
        expected = n * (n - 1) // 2
        assert out == expected"
    },
    {
      "name": "test_v_eq_n_minus_1_case",
      "source": "def test_v_eq_n_minus_1_case(run, x):
    out_str = run(x).strip()
    out = int(out_str)
    n, v = map(int, x.strip().split())
    if v == n - 1:
        assert out == n - 1"
    },
    {
      "name": "test_greedy_simulation",
      "source": "def test_greedy_simulation(run, x):
    out_str = run(x).strip()
    out = int(out_str)
    n, v = map(int, x.strip().split())
    cost = 0
    fuel = 0
    for i in range(1, n):
        remaining = n - i
        if fuel < remaining:
            buy = min(v - fuel, remaining - fuel)
            cost += buy * i
            fuel += buy
        fuel -= 1
    assert out == cost"
    }
  ]
}
